"""Generate the English report from preserved synthetic receipts, never private audio."""
import datetime,html,json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parent
STATIC=ROOT/'static'
def read(p):return json.loads(p.read_text())
def esc(v):return html.escape(str(v))
def latest(pattern):return sorted(STATIC.glob(pattern))[-1]
def table(headers,rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def stats(values):
    xs=sorted(values);n=len(xs);p=(n-1)*.95;lo=int(p)
    return round(statistics.median(xs),2),round(xs[lo]+(xs[min(lo+1,n-1)]-xs[lo])*(p-lo),2)
def main():
    path=latest('environment-expanded-all-*.json');browser=read(path)
    events=read(STATIC/'environment-event-tagger.json');units=read(ROOT/'logs/unit-checks.json')
    music_path=latest('environment-music-*.json');music=read(music_path)
    general=read(STATIC/'two-stage-browser.json');memory=read(STATIC/'two-stage-memory-browser.json')
    diversity_path=STATIC/'environment-diversity.json'
    diversity=read(diversity_path) if diversity_path.exists() else {}
    checks={'generated':datetime.datetime.now(datetime.timezone.utc).isoformat(),
        'source_sha256':browser['source_sha256'],'unit_tests':units,'expanded_receipt':path.name,
        'expanded_passed':browser['passed'],'music_receipt':music_path.name,'music_passed':music['passed'],
        'memory_regression_passed':memory['passed'],'memory_source_sha256':memory['source_sha256'],
        'conversation_regression_passed':general['passed'],'conversation_source_sha256':general['source_sha256']}
    (STATIC/'environment-release-checks.json').write_text(json.dumps(checks,indent=2))
    verification=[('Offline regression',str(units['tests'])+' passed' if units['passed'] else 'FAILED','No network, physical microphone or model accuracy claim.'),
        ('Expanded HTTPS suite',str(len(browser['cases']))+' cases passed' if browser['passed'] else 'FAILED','Actual CPU/GPU models, Parakeet, Qwen, TTS and browser PCM scheduling. Synthetic digital input.'),
        ('Browser fake microphone','PASS' if music['passed'] else 'FAILED','Real capture worklet; quiet music, music response, repeat cooldown, no false user turn.'),
        ('Memory after reconnect','PASS' if memory['passed'] else 'FAILED','Local reaction remembers Alice using opt-in wiki with zero recent-history budget; off/reset verified.'),
        ('Reply flow and UI','PASS' if general['passed'] else 'FAILED','Optional reaction → informed main answer; poem, off switch, cancellation and mobile layout. Receipt includes its source revision.')]
    case_rows=[]
    for row in browser['cases']:
        name=row['case'];meaning='Inspect exact reply; routing/completion is the automated assertion.'
        if name=='glass_breaking':meaning='SEMANTIC ERROR: described as a drum/impact instead of identifying glass.'
        if name=='dog':meaning='Wording defect: invented “Hundegefühl”; not a good user-facing description.'
        if name=='cat':meaning='Tentative cat identification is consistent with the source.'
        if 'music' in name:meaning='Music acknowledged/answered; precise instrument descriptions are not verified.'
        case_rows.append((name,'PASS' if row.get('passed') else 'FAILED',row.get('pcm_chunks','see event receipt'),row.get('reply',''),meaning))
    timings=[]
    def add(label,values,note):
        m,p=stats(values);timings.append((label,len(values),f'{m} ms',f'{p} ms',note))
    add('CPU MN04 worker, full clip + time windows',[r['tags']['total_ms'] for r in events['rows']], '14 five-second diagnostic clips; two CPU threads. No VRAM.')
    add('Caption only, HTTP wall time',[r['wall_ms'] for r in events['timings'] if r['mode']=='caption_only'],'3.2-second identical authored music; alternating order.')
    add('Caption + MN04, parallel HTTP wall time',[r['wall_ms'] for r in events['timings'] if r['mode']=='parallel'],'Same music; six repetitions. Difference is timing variation, not proof of speedup.')
    caps=[c for row in browser['cases'] for c in row.get('captions',[]) if c.get('status')=='available']
    if caps:
        add('Caption + optional tags inside live session',[c['request_ms'] for c in caps],'Includes local HTTP; excludes capture, conversational pause, LLM and TTS.')
    examples=[]
    for row in events['rows']:
        examples.append((row['fixture'],row['caption'].get('caption',''),'; '.join(f"{c['label']} {c['score']:.3f}" for c in row['tags']['candidates'][:3]),row['tags']['total_ms']))
    receipt_paths=sorted(STATIC.glob('environment-*.json'))+[STATIC/'two-stage-browser.json',STATIC/'two-stage-memory-browser.json']
    links=''.join(f'<li><a href="{esc(p.name)}">{esc(p.name)}</a></li>' for p in receipt_paths)
    routed=sum(bool(r.get('routed')) for r in diversity.get('rows',[]));total=len(diversity.get('rows',[]))
    report=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby: parallel sound events, music and conversation tests</title>
<style>body{{font:16px/1.6 system-ui,sans-serif;color:#24363d;background:#f6f7f4;max-width:1200px;margin:auto;padding:24px}}h1,h2{{line-height:1.2}}section{{background:white;border:1px solid #dce3df;border-radius:16px;margin:22px 0;padding:24px}}a{{color:#126b70}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{text-align:left;vertical-align:top;border-bottom:1px solid #dce3df;padding:10px}}th{{background:#edf3f0}}.scroll{{overflow:auto}}pre{{overflow:auto;background:#eef3f0;padding:16px;border-radius:8px}}code{{overflow-wrap:anywhere}}.flow{{border-left:4px solid #42a090;padding:12px;background:#f1f8f5}}small{{color:#53676d}}summary{{cursor:pointer}}</style></head><body>
<nav><a href="https://diane-asylum-understood-invoice.trycloudflare.com/desk-robot/">Live Robby</a> · <a href="https://github.com/LAION-AI/Humaneness-Voice/tree/main/robby">Source</a> · <a href="VOICE_ASSISTANT_TEST_PROTOCOL.md">Reproducible test protocol</a></nav>
<h1>Parallel sound candidates for Robby</h1><p>Updated {esc(checks['generated'])}. EfficientAT MN04 supplies small, independent AudioSet hints alongside GPU sound captioning. Normal ASR does not wait for this optional branch. This report separates working data flow from actual recognition quality.</p>
<section><h2>Findings first</h2>{table(['Check','Result','What was verified'],verification)}<p><strong>Useful but fallible:</strong> candidate labels helped expose rain, vehicle and cat sounds that the captioner described differently. They can also be wrong: rhythmic impacts received a high Music score. The browser completed its routes and speech playback, but the dog wording and glass-break interpretation still need improvement. No physical room, microphone-array or representative accuracy claim is made.</p><p>Runtime fingerprint for the expanded suite: <code>{browser['source_sha256']}</code>. Each other receipt records its own revision; a prior result is not silently relabeled as a current test.</p></section>
<section><h2>What is now available</h2><ul><li><strong>AudioSet event candidates</strong>: enabled by default, independently switchable under “Proactive listening &amp; sounds”. Top candidates and a CPU timing card are visible.</li><li><strong>Sound threshold: 8 dB</strong> above the learned room floor. Browser noise suppression/automatic gain are off in Preserve sounds mode; echo cancellation stays on.</li><li><strong>Music present at startup</strong> gets a bounded periodic probe. Sustained sounds collect more context; repeated music comments are suppressed for three minutes.</li><li><strong>Ask then play:</strong> “Was ist das hier?” or “What is that sound?” arms an approximately 2.4-second after-question window. Ordinary questions have no added listening wait.</li><li><strong>Local reactions OFF by default.</strong> When enabled, the short validated reaction sees authorized memory/sound context and its exact text enters Qwen before the main answer starts. Reaction playback overlaps main generation and shared-model TTS. No second filler bridge.</li><li><strong>Open foreground conversation:</strong> no wake phrase required; unknown speakers receive a session label and a name question. A separate quiet-background filter and optional partner focus remain available. Camera and persistent wiki memory remain off by default.</li></ul></section>
<section><h2>Why this small model</h2>{table(['Candidate','Scope','Decision'],[('EfficientAT MN04','983,599 parameters; 4,066,513-byte checkpoint; 527 AudioSet labels','Implemented on two CPU threads. Fits existing PyTorch stack and leaves VRAM to speech.'),('EfficientAT MN10','Upstream larger 4.88-M parameter variant','Possible follow-up accuracy/latency trade-off; not benchmarked here.'),('YAMNet','MobileNet-based AudioSet classifier, 521 classes','Valid lightweight alternative; not deployed or benchmarked. Would introduce a different model runtime/conversion path.')])}<p>Sources: <a href="https://github.com/fschmid56/EfficientAT">EfficientAT official repository and model table</a>; <a href="https://www.tensorflow.org/hub/tutorials/yamnet">official YAMNet documentation</a>. AudioSet is the label/training resource, not a spatial localizer. Upstream benchmark numbers are not Robby test accuracy.</p><p>MN04 revision <code>a425fdce92572e602a1d5634799bd9f1f2efa806</code>; checkpoint SHA256 <code>899a8c6217063f6941793102a2780b3dd788ab11fce468d9cf5f0577c453321c</code>. Bootstrap downloads only eight inference/source files and one small weight file, retaining the upstream MIT license. CPU inference uses FP32; upstream notes that precision can affect results.</p></section>
<section><h2>Parallel data flow and bounded delay</h2><div class="flow">Existing microphone → existing ASR / speaker identity<br>Same microphone → salience + playback guard → <strong>GPU Whisper captioner ∥ CPU MN04 candidates</strong><br>Caption + optional ranked labels / time windows → uncertain observation → authorized conversation context → Qwen → streaming TTS</div><p>The two models receive the same captured audio independently. MN04 does <strong>not</strong> become a required serial gate before Whisper. Its request has a 180-ms deadline; unavailable, overloaded or late hints are dropped. The CPU worker accepts one job at a time and rejects a stale-work queue. The deadline overlaps the caption request; in the unusual case of a faster caption, joining can extend that branch up to the event deadline. Microphone ingress and normal ASR never wait for it.</p><p>Labels do not re-prompt Whisper's decoder. They join its caption as a second evidence source for the LLM. A strong music-vs-speech hint can also correct routing. This avoids an extra serial caption pass. Disagreement is passed explicitly as uncertainty, not resolved by treating an uncalibrated score as truth.</p><p><strong>Temporal, not spatial:</strong> overlapping 1.28-second windows with 0.64-second stride show where a category was suggested. These are coarse classifier windows, not trained event boundaries. A mono microphone cannot supply a reliable left/right angle; spatial localization requires suitable synchronized microphone hardware and another algorithm.</p></section>
<section><h2>Measured cost</h2>{table(['Measurement','n','Median','p95 (interpolated)','Definition'],timings)}<p>The paired test alternates six caption-only and six parallel requests on identical audio. Lower parallel wall time in this small run is timing variation, not an acceleration claim. Capture/context collection (about 1.6 seconds for transients, 3.2 for sustained sounds), idle scheduling, API generation, TTS and browser buffering remain separate. CPU classification time is not microphone-to-ear latency.</p></section>
<section><h2>Actual model outputs</h2><p>First two fixed metadata rows per class, not selected for successful predictions. Twelve public ESC-50 clips plus two authored controls. Original audio stays in the excluded local cache; exact URLs, hashes and license credits are recorded in the receipts.</p>{table(['Input label','GPU caption, fallible','CPU top 3, uncalibrated scores','CPU ms'],examples)}<p>The caption-only detector replay routed {routed}/{total} examples across onset, forced-positive VAD and already-playing modes. Routing is not correctness. In particular, music-like impacts, cat/siren confusion, vague rain descriptions and glass/impact confusion prevent any claim of perfect recognition. Raising thresholds alone would also discard genuine quiet sounds.</p></section>
<section><h2>Actual HTTPS conversation cases</h2>{table(['Case','Data-flow check','PCM chunks','Generated reply','Meaning / limitation'],case_rows)}<p>Expanded tests inject deterministic PCM through the actual browser's 20-ms microphone sender, including playback-position tags. The separate music test uses Chrome's fake microphone through the capture worklet. Real model services, hosted/local LLMs and TTS are used. Completion and PCM scheduling do not certify a human listener's physical speakers.</p><p>The earlier “text shown but not spoken” bug was premature browser cancellation: raw level/VAD could cancel an optional environmental reply even when the activity was just sound. Environmental replies now ignore that generic browser cancellation source. Server-verified user interruption, Stop and manual controls remain active. The music test injects high level/VAD during a reply and checks that it sends no false <code>avatar:cancel</code>. The UI distinguishes waiting-for-audio, scheduled audio and cancellation.</p></section>
<section><h2>Speech addressed to Robby versus background</h2><p>The conservative heuristic requires <strong>all three</strong>: relative level below 0.28 of the session reference, no confident known-voice match (cosine below 0.62), and no explicit address or self-introduction. With no reference it accepts the speaker. Loudness and estimated SNR alone are not intent classifiers. The filter is independent and can be disabled.</p><p>The speaker browser replay covers Christoph, an unfamiliar foreground guest, “Ich bin Selma”, later Selma and quiet unrelated background speech at gain 0.1. A narrow recent-name-answer rule can attach a lower-confidence vocal variant to the just-created unnamed guest, avoiding a duplicate person. This does not guarantee rejection of loud TV or acceptance of every soft user. The protocol defines a held-out voice/level/noise matrix for further threshold search.</p></section>
<section><h2>Reproduce, extend and inspect failures</h2><pre>python run_unit_checks.py
python bootstrap_sound_events.py
# Separate loopback process; existing GPU caption worker is also required:
python sound_event_worker.py
python check_sound_events.py
python check_environment_diversity.py
# Sequential browser sessions, with the normal demo stack running:
python browser_environment_music.py --url https://YOUR-DEMO
python browser_environment_expanded.py --url https://YOUR-DEMO --group all
python browser_two_stage_check.py --url https://YOUR-DEMO
python browser_two_stage_memory.py --url https://YOUR-DEMO</pre><p>The main launcher accepts <code>--with-sound-captions</code> for both sidecars. Use matching PyTorch/torchaudio/torchvision wheels; tested 2.6.0+cu124 / 2.6.0+cu124 / 0.21.0+cu124. Optional event settings: <code>ROBO_EVENT_CACHE</code>, <code>ROBO_EVENT_URL</code>, <code>ROBO_EVENT_PORT</code>. Default loopback port: 8804. Runtime audio is held briefly in RAM and not saved.</p><p>The <a href="VOICE_ASSISTANT_TEST_PROTOCOL.md">test protocol</a> separates required future scenarios from executed evidence and describes licenses, scene generation, physical-room limitations and controlled threshold searches. Retained failed attempts include a busy public ASR slot, a generic after-question reply and a speaker-name split. They are not silently deleted or reported as passes. The older report is <a href="environment-report-before-parallel-events.html">archived here</a>.</p><p>Recommended next steps: blind semantic rating on held-out sound mixtures; ablate MN04 vs MN10 on identical clips; music-plus-speech and real singing; loud television versus quiet addressed speech; actual room/echo/device tests. Fine-grained event boundaries or direction-of-arrival would need a separately validated model/hardware path.</p><details><summary>All raw measurement and browser receipts</summary><ul>{links}</ul></details></section></body></html>'''
    (STATIC/'environment-report.html').write_text(report)
    print(json.dumps(checks))
if __name__=='__main__':main()
